import pandas as pd


def _get_input(inputs: dict, *names):
    for n in names:
        if n in inputs:
            return inputs[n]
    # fallback: case-insensitive match
    lower_map = {k.lower(): k for k in inputs.keys()}
    for n in names:
        if n.lower() in lower_map:
            return inputs[lower_map[n.lower()]]
    raise KeyError(f"None of {names} found in inputs keys: {list(inputs.keys())}")


def run(inputs: dict) -> dict:
    dim = _get_input(inputs, "DIM_ACCOUNT", "dim_account").copy()
    stg = _get_input(inputs, "STG_ACCOUNT", "stg_account").copy()

    # Normalize date columns
    dim["eff_start_date"] = pd.to_datetime(dim["eff_start_date"])
    dim["eff_end_date"] = pd.to_datetime(dim["eff_end_date"])
    stg["update_date"] = pd.to_datetime(stg["update_date"])

    # Build in-memory version store: account_id -> list of version dicts
    versions = {}
    for row in dim.itertuples(index=False):
        acc = row.account_id
        versions.setdefault(acc, []).append(
            {
                "plan": row.plan,
                "eff_start_date": row.eff_start_date,
                "eff_end_date": row.eff_end_date,
                "is_current": row.is_current,
            }
        )

    # Process staged records in order: account_id, update_date ascending
    stg_sorted = stg.sort_values(
        by=["account_id", "update_date"], kind="mergesort"
    ).reset_index(drop=True)

    def plans_equal(p1, p2):
        n1 = pd.isna(p1)
        n2 = pd.isna(p2)
        if n1 and n2:
            return True
        if n1 or n2:
            return False
        return p1 == p2

    for row in stg_sorted.itertuples(index=False):
        acc = row.account_id
        s_plan = row.plan
        s_date = row.update_date

        vlist = versions.setdefault(acc, [])

        if not vlist:
            vlist.append(
                {
                    "plan": s_plan,
                    "eff_start_date": s_date,
                    "eff_end_date": pd.NaT,
                    "is_current": 1,
                }
            )
            continue

        # find covering version: start <= s_date < end (end NULL = open/infinite)
        cover = None
        for v in vlist:
            start = v["eff_start_date"]
            end = v["eff_end_date"]
            if start <= s_date and (pd.isna(end) or s_date < end):
                cover = v
                break

        if cover is None:
            # s_date is earlier than the account's first version
            earliest = min(vlist, key=lambda v: v["eff_start_date"])
            vlist.append(
                {
                    "plan": s_plan,
                    "eff_start_date": s_date,
                    "eff_end_date": earliest["eff_start_date"],
                    "is_current": 0,
                }
            )
        else:
            if plans_equal(cover["plan"], s_plan):
                # no-op
                pass
            elif s_date == cover["eff_start_date"]:
                # same-day correction, no new version
                cover["plan"] = s_plan
            else:
                # split v at s_date
                new_v = {
                    "plan": s_plan,
                    "eff_start_date": s_date,
                    "eff_end_date": cover["eff_end_date"],
                    "is_current": cover["is_current"],
                }
                vlist.append(new_v)
                cover["eff_end_date"] = s_date
                cover["is_current"] = 0

    # Flatten result
    out_rows = []
    for acc, vlist in versions.items():
        for v in vlist:
            out_rows.append(
                {
                    "account_id": acc,
                    "plan": v["plan"],
                    "eff_start_date": v["eff_start_date"],
                    "eff_end_date": v["eff_end_date"],
                    "is_current": v["is_current"],
                }
            )

    out_df = pd.DataFrame(
        out_rows,
        columns=["account_id", "plan", "eff_start_date", "eff_end_date", "is_current"],
    )

    if not out_df.empty:
        out_df = out_df.sort_values(
            by=["account_id", "eff_start_date"], kind="mergesort"
        ).reset_index(drop=True)

    return {"dim_account_out": out_df}
